import React,{useEffect,useMemo,useState} from 'react';
import {createClient} from '@supabase/supabase-js';
import {LayoutDashboard,Users,Car,UserRound,Route,ClipboardList,Receipt,Wallet,Building2,ChartNoAxesCombined,Settings as SettingsIcon,Search,Plus,Download,Save,LogOut,Menu,X,RefreshCw,Archive,Edit,Trash2,CheckCircle2,AlertTriangle,FileSpreadsheet} from 'lucide-react';
import './style.css';

const url=import.meta.env.VITE_SUPABASE_URL, key=import.meta.env.VITE_SUPABASE_ANON_KEY;
const supabase=url&&key?createClient(url,key):null;
const today=()=>new Date().toLocaleDateString('en-CA');
const month=()=>today().slice(0,7);
const id=()=>crypto.randomUUID();
const money=n=>'NPR '+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2});
const nav=[['Dashboard',LayoutDashboard],['Owners',Users],['Vehicles',Car],['Drivers',UserRound],['Daily Tracking',Route],['Rides',ClipboardList],['Expenses',Receipt],['Driver Payroll',Wallet],['Owner Settlements',Building2],['Reports',ChartNoAxesCombined],['Settings',SettingsIcon]];
const empty={owners:[],vehicles:[],drivers:[],agreements:[],readings:[],rides:[],expenses:[],driverPayments:[],ownerPayments:[],categories:[{id:'demo-cat-1',name:'Vehicle charging',active:true},{id:'demo-cat-2',name:'Vehicle maintenance',active:true},{id:'demo-cat-3',name:'Driver food',active:true},{id:'demo-cat-4',name:'Driver allowance',active:true},{id:'demo-cat-5',name:'Vehicle cleaning',active:true},{id:'demo-cat-6',name:'Other expenses',active:true}],settings:{commission:10}};
const tables={owners:'owners',vehicles:'vehicles',drivers:'drivers',agreements:'driver_compensation_agreements',readings:'daily_vehicle_readings',rides:'rides',expenses:'expenses',driverPayments:'driver_payments',ownerPayments:'owner_payments',categories:'expense_categories'};
const toSnake=s=>s.replace(/[A-Z]/g,m=>'_'+m.toLowerCase());
const toCamel=s=>s.replace(/_([a-z])/g,(_,c)=>c.toUpperCase());
const normalize=(o)=>Object.fromEntries(Object.entries(o||{}).map(([k,v])=>[toCamel(k),v]));
const serialize=(o)=>Object.fromEntries(Object.entries(o).filter(([k])=>!['createdAt','updatedAt','ownerName','driverName','vehicleRegistration'].includes(k)).map(([k,v])=>[toSnake(k),v]));
const commissionTypeToDb=v=>({'None':'none','Percentage':'percentage','Fixed per ride':'fixed_per_ride','none':'none','percentage':'percentage','fixed_per_ride':'fixed_per_ride'}[v]||'none');
const commissionTypeFromDb=v=>({'none':'None','percentage':'Percentage','fixed_per_ride':'Fixed per ride'}[v]||'None');
function fromDb(kind,row){const n=normalize(row||{});
 if(kind==='owners'||kind==='vehicles'||kind==='drivers'||kind==='categories') n.active=n.isActive??true;
 if(kind==='vehicles') n.registration=n.registrationNumber;
 if(kind==='drivers') n.name=n.fullName;
 if(kind==='agreements'){n.fixedMonthlySalary=n.fixedMonthlySalary??n.monthlySalary??0;n.commissionType=commissionTypeFromDb(n.commissionType);}
 if(kind==='readings'){n.driverId=n.morningDriverId;n.odometer=n.openingOdometer;n.batteryPercent=n.startingBatteryPercent;}
 if(kind==='rides'){n.rideDate=n.rideDatetime?.slice(0,10);n.rideTime=n.rideDatetime?.slice(11,16);n.vehicleNumber=n.vehicleRegistration||'';n.driverName=n.driverFullName||'';n.appFare=n.appFare??0;n.sameFare=!!n.fareSameAsApp;n.nepcabCommission=n.nepcabCommissionAmount??0;n.driverCommission=n.driverCommissionAmount??0;n.commissionRateApplied=n.nepcabCommissionRate??10;}
 if(kind==='driverPayments'||kind==='ownerPayments'){n.periodMonth=n.periodStart;n.paymentDate=n.paidAt?.slice(0,10);n.breakdown=n.statementSnapshot??n.breakdown;}
 if(kind==='expenses') n.categoryId=n.categoryId||null;
 return n;
}
function toDb(kind,r){
 const base={id:r.id};
 if(kind==='owners') return {...base,name:r.name,phone:r.phone,address:r.address,category:r.category,is_active:r.active!==false};
 if(kind==='vehicles') return {...base,registration_number:r.registration,owner_id:r.ownerId,vehicle_type:r.vehicleType||null,initial_odometer:Number(r.initialOdometer||0),is_active:r.active!==false};
 if(kind==='drivers') return {...base,full_name:r.name,phone:r.phone,address:r.address,is_active:r.active!==false};
 if(kind==='agreements') return {...base,driver_id:r.driverId,effective_from:r.effectiveFrom,effective_to:r.effectiveTo||null,monthly_salary:Number(r.fixedMonthlySalary??r.monthlySalary??r.salary??0),commission_type:commissionTypeToDb(r.commissionType),commission_value:Number(r.commissionValue||0)};
 if(kind==='readings') return {...base,vehicle_id:r.vehicleId,reading_date:r.readingDate,morning_driver_id:r.driverId||null,opening_odometer:Number(r.odometer),starting_battery_percent:r.batteryPercent===''||r.batteryPercent==null?null:Number(r.batteryPercent),notes:r.notes||null};
 if(kind==='rides') return {...base,ride_id:r.rideId,ride_datetime:r.rideDatetime,booking_type:r.bookingType,passenger_name:r.passengerName,passenger_phone:r.passengerPhone||null,vehicle_id:r.vehicleId,owner_id:r.ownerId,driver_id:r.driverId,pickup_location:r.pickupLocation,dropoff_location:r.dropoffLocation,app_fare:Number(r.appFare),agreed_fare:Number(r.agreedFare),fare_same_as_app:!!r.sameFare,nepcab_commission_rate:Number(r.commissionRateApplied??10),nepcab_commission_basis:'agreed_fare',nepcab_commission_amount:Number(r.nepcabCommission||0),driver_agreement_id:r.driverAgreementId||null,driver_commission_type:commissionTypeToDb(r.driverCommissionType),driver_commission_value:Number(r.driverCommissionValue||0),driver_commission_amount:Number(r.driverCommission||0),notes:r.notes||null};
 if(kind==='expenses') return {...base,expense_date:r.expenseDate,category_id:r.categoryId||null,vehicle_id:r.vehicleId||null,driver_id:r.driverId||null,amount:Number(r.amount),description:r.description||r.notes||null};
 if(kind==='categories') return {...base,name:r.name,is_active:r.active!==false};
 if(kind==='driverPayments') return {...base,driver_id:r.driverId,period_start:r.periodMonth,period_end:r.periodEnd||r.periodMonth,amount:Number(r.amount),paid_at:r.paidAt||r.paymentDate||new Date().toISOString(),notes:r.note||r.notes||null};
 if(kind==='ownerPayments') return {...base,owner_id:r.ownerId,period_start:r.periodMonth,period_end:r.periodEnd||r.periodMonth,amount:Number(r.amount),paid_at:r.paidAt||r.paymentDate||new Date().toISOString(),statement_snapshot:r.breakdown||{},notes:r.notes||null};
 return serialize(r);
}
function App(){
 const [data,setData]=useState(empty),[page,setPage]=useState('Dashboard'),[search,setSearch]=useState(''),[period,setPeriod]=useState(month()),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[session,setSession]=useState(null),[login,setLogin]=useState({email:'',password:''}),[modal,setModal]=useState(null),[mobile,setMobile]=useState(false),[selected,setSelected]=useState(null),[tab,setTab]=useState('entry');
 const flash=m=>{setNotice(m);setTimeout(()=>setNotice(''),3500)};
 const localKey='nepcab-v3-demo';
 const load=async()=>{if(!supabase){const raw=localStorage.getItem(localKey);if(raw)try{setData({...empty,...JSON.parse(raw)})}catch{};return;}
  setBusy(true);const result={...empty};for(const [keyName,table] of Object.entries(tables)){const {data:rows,error}=await supabase.from(table).select('*').order('created_at',{ascending:false}).limit(5000);if(error){console.error(table,error);flash(`Could not load ${table}: ${error.message}`);continue;}result[keyName]=(rows||[]).map(row=>fromDb(keyName,row));}
  const {data:rates,error:rateError}=await supabase.from('commission_rates').select('*').order('effective_from',{ascending:false}).limit(1);if(rateError){console.error('commission_rates',rateError);}result.settings.commission=Number(rates?.[0]?.rate??10);
  result.rides=result.rides.filter(r=>!r.deletedAt).map(r=>({...r,vehicleNumber:result.vehicles.find(v=>v.id===r.vehicleId)?.registration||'',driverName:result.drivers.find(d=>d.id===r.driverId)?.name||''}));result.expenses=result.expenses.map(e=>({...e,category:result.categories.find(c=>c.id===e.categoryId)?.name||''}));setData(result);setBusy(false);
 };
 useEffect(()=>{if(!supabase){load();return;}supabase.auth.getSession().then(({data:{session}})=>{setSession(session);if(session)load()});const {data:{subscription}}=supabase.auth.onAuthStateChange((_e,s)=>{setSession(s);if(s)load();else setData(empty)});return()=>subscription.unsubscribe();},[]);
 useEffect(()=>{if(!supabase)localStorage.setItem(localKey,JSON.stringify(data));},[data]);
 const write=async(keyName,record,editing=false)=>{const table=tables[keyName];if(supabase){const payload=toDb(keyName,record);if(keyName==='expenses'&&!payload.category_id){const match=data.categories.find(c=>c.name===record.category);if(match)payload.category_id=match.id;}let q=editing?supabase.from(table).update(payload).eq('id',record.id).select().single():supabase.from(table).insert(payload).select().single();const {data:out,error}=await q;if(error){flash(error.message);return false;}if(out)record=fromDb(keyName,out);}setData(d=>({...d,[keyName]:editing?d[keyName].map(x=>x.id===record.id?record:x):[record,...d[keyName]]}));flash(editing?'Changes saved':'Record saved');return true;};
 const remove=async(keyName,record)=>{if(!confirm('Delete this record? This action cannot be undone.'))return;if(supabase){const {error}=await supabase.from(tables[keyName]).delete().eq('id',record.id);if(error){flash(error.message);return;}}setData(d=>({...d,[keyName]:d[keyName].filter(x=>x.id!==record.id)}));flash('Record deleted');};
 const archive=async(keyName,record)=>{if(!confirm('Deactivate this record? Historical transactions will be preserved.'))return;await write(keyName,{...record,active:false},true)};
 const activeOwners=data.owners.filter(x=>x.active!==false),activeVehicles=data.vehicles.filter(x=>x.active!==false),activeDrivers=data.drivers.filter(x=>x.active!==false);
 const ownerForVehicle=vid=>data.vehicles.find(v=>v.id===vid)?.ownerId;
 const driverAgreement=(driverId,date)=>{const ds=data.agreements.filter(x=>x.driverId===driverId&&x.effectiveFrom<=date&&(!x.effectiveTo||x.effectiveTo>=date)).sort((a,b)=>b.effectiveFrom.localeCompare(a.effectiveFrom));return ds[0]||null;};
 const commissionFor=(fare)=>Number(fare||0)*(Number(data.settings.commission??10)/100);
 const rideRows=data.rides.filter(r=>(r.rideDatetime||r.date||'').slice(0,7)===period);
 const expenseRows=data.expenses.filter(e=>(e.expenseDate||e.date||'').slice(0,7)===period);
 const totals=useMemo(()=>({rides:rideRows.length,gross:rideRows.reduce((s,r)=>s+Number(r.agreedFare??r.agreed??0),0),commission:rideRows.reduce((s,r)=>s+Number(r.nepcabCommission??r.commission??0),0),driverCommission:rideRows.reduce((s,r)=>s+Number(r.driverCommission||0),0),expenses:expenseRows.reduce((s,e)=>s+Number(e.amount||0),0)}),[rideRows,expenseRows]);
 const saveRecord=(k,r,editing=false)=>write(k,r,editing);
 const csv=(rows,name)=>{if(!rows.length){flash('No records to export');return;}const cols=Object.keys(rows[0]),content=[cols.join(','),...rows.map(r=>cols.map(c=>'"'+String(r[c]??'').replaceAll('"','""')+'"').join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+content],{type:'text/csv;charset=utf-8'}));a.download=name+'.csv';a.click();URL.revokeObjectURL(a.href);};
 const go=p=>{setPage(p);setSearch('');setSelected(null);setTab('entry');setMobile(false)};
 const signIn=async e=>{e.preventDefault();setBusy(true);const {error}=await supabase.auth.signInWithPassword(login);setBusy(false);if(error)flash(error.message)};
 if(supabase&&!session)return <div className="login"><form className="login-card" onSubmit={signIn}><div className="brand-mark">N</div><h1>NepCab Fleet</h1><p>Staff access · Supabase</p><label>Email<input type="email" required value={login.email} onChange={e=>setLogin({...login,email:e.target.value})}/></label><label>Password<input type="password" required value={login.password} onChange={e=>setLogin({...login,password:e.target.value})}/></label><button className="primary full" disabled={busy}>{busy?'Signing in…':'Sign in'}</button></form></div>;
 const common={data,setData,search,setSearch,period,setPeriod,saveRecord,remove,archive,activeOwners,activeVehicles,activeDrivers,ownerForVehicle,commissionFor,driverAgreement,csv,flash,selected,setSelected};
 return <div className="app"><aside className={'sidebar '+(mobile?'show':'')}><div className="brand"><div className="brand-mark">N</div><div><b>NepCab</b><small>Fleet Management v3</small></div><button className="icon-btn mobile-close" onClick={()=>setMobile(false)}><X/></button></div><div className="nav-label">WORKSPACE</div>{nav.map(([n,I])=><button key={n} className={'nav-item '+(page===n?'active':'')} onClick={()=>go(n)}><I size={18}/><span>{n}</span></button>)}<div className="sidebar-bottom"><div className="connection"><span className={'dot '+(supabase?'green':'amber')}/>{supabase?'Supabase configured':'Local demo mode'}</div><small>{supabase?'Authenticated database':'Browser demo storage'} · NPR</small></div></aside><main className="main"><header className="topbar"><button className="icon-btn menu-btn" onClick={()=>setMobile(true)}><Menu/></button><div className="crumb">NepCab <b>/ {page}</b></div><div className="top-actions">{busy&&<span className="muted">Loading…</span>}{supabase&&<button className="secondary small" onClick={load}><RefreshCw size={14}/> Refresh</button>}{supabase&&<button className="icon-btn" onClick={()=>supabase.auth.signOut()}><LogOut size={17}/></button>}</div></header><section className="content">
 {page==='Dashboard'&&<Dashboard {...common} totals={totals} go={go}/>}
 {page==='Owners'&&<Master {...common} kind="owners" title="Owners" fields={[['name','Owner name','text',true],['phone','Phone (10 digits)','tel',true],['address','Address','text',true],['category','Category','select',true,['Local','Remote']] ]}/>}
 {page==='Vehicles'&&<Master {...common} kind="vehicles" title="Vehicles" fields={[['registration','Registration number','text',true],['ownerId','Owner','owner',true],['initialOdometer','Initial odometer (km)','number',true],['status','Status','select',true,['Active','Inactive']] ]}/>}
 {page==='Drivers'&&<Master {...common} kind="drivers" title="Drivers" fields={[['name','Full name','text',true],['phone','Phone (10 digits)','tel',true],['address','Address','text',true],['salary','Monthly fixed salary (NPR)','number',false],['commissionType','Commission type','select',true,['None','Percentage','Fixed per ride']],['commissionValue','Commission value','number',false],['effectiveFrom','Effective from','date',true]]}/>}
 {page==='Daily Tracking'&&<Tracking {...common}/>}
 {page==='Rides'&&<Rides {...common}/>}
 {page==='Expenses'&&<Expenses {...common}/>}
 {page==='Driver Payroll'&&<Payroll {...common}/>}
 {page==='Owner Settlements'&&<Settlements {...common}/>}
 {page==='Reports'&&<Reports {...common} totals={totals} go={go}/>}
 {page==='Settings'&&<SettingsPage {...common} supabase={supabase}/>}
 </section></main>{notice&&<div className="toast">{notice}</div>}</div>;
}
function Header({title,desc,actions}){return <div className="page-head"><div><h1>{title}</h1><p>{desc}</p></div><div className="head-actions">{actions}</div></div>}
function Empty({text}){return <div className="empty"><b>{text}</b></div>}
function Toolbar({search,setSearch,placeholder='Search records…',actions}){return <div className="toolbar"><div className="search"><Search size={16}/><input placeholder={placeholder} value={search} onChange={e=>setSearch(e.target.value)}/></div>{actions}</div>}
function InputField({field,value,onChange,options=[],data}){const [k,label,type,required,choices]=field;let opts=choices||options;if(type==='owner')opts=(data?.owners||[]).filter(x=>x.active!==false).map(x=>[x.id,`${x.name} — ${x.phone}`]);if(type==='vehicle')opts=(data?.vehicles||[]).filter(x=>x.active!==false).map(x=>[x.id,x.registration]);if(type==='driver')opts=(data?.drivers||[]).filter(x=>x.active!==false).map(x=>[x.id,`${x.name} — ${x.phone}`]);return <label>{label}{type==='select'||['owner','vehicle','driver'].includes(type)?<select required={required} value={value??''} onChange={e=>onChange(e.target.value)}><option value="">Select…</option>{opts.map(o=>Array.isArray(o)?<option key={o[0]} value={o[0]}>{o[1]}</option>:<option key={o}>{o}</option>)}</select>:<input required={required} type={type==='tel'?'tel':type} min={type==='number'?0:undefined} value={value??''} onChange={e=>onChange(type==='number'?e.target.value:e.target.value)}/>}</label>}
function FormModal({title,fields,initial={},data,onClose,onSave,extra}){const [v,setV]=useState(initial);return <div className="overlay" onClick={onClose}><form className="modal" onSubmit={e=>{e.preventDefault();onSave(v)}} onClick={e=>e.stopPropagation()}><div className="modal-head"><h3>{title}</h3><button type="button" className="icon-btn" onClick={onClose}><X/></button></div><div className="modal-body">{fields.map(f=><InputField key={f[0]} field={f} value={v[f[0]]} onChange={x=>setV(p=>({...p,[f[0]]:x}))} data={data}/>) }{extra?.(v,setV)}</div><div className="modal-foot"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary"><Save size={15}/> Save</button></div></form></div>}
function Master(p){const {kind,title,data,search,setSearch,saveRecord,archive}=p;const [modal,setModal]=useState(null);const driverRows=kind==='drivers'?data.drivers.map(d=>{const a=data.agreements.filter(x=>x.driverId===d.id).sort((x,y)=>(y.effectiveFrom||'').localeCompare(x.effectiveFrom||''))[0];return {...d,salary:a?.fixedMonthlySalary??d.salary??0,commissionType:a?.commissionType??d.commissionType??'None',commissionValue:a?.commissionValue??d.commissionValue??0,effectiveFrom:a?.effectiveFrom??d.effectiveFrom??''}}):data[kind];const rows=driverRows.filter(x=>JSON.stringify(x).toLowerCase().includes(search.toLowerCase()));const editFields=p.fields;const save=async v=>{if((kind==='owners'||kind==='drivers')&&!/\p{L}/u.test(v.name||''))return alert('Enter a valid name containing letters.');if(kind==='owners'&&(!/^\d{10}$/.test(v.phone||'')))return alert('Enter a valid 10-digit Nepal phone number.');if(kind==='drivers'&&(!/^\d{10}$/.test(v.phone||'')))return alert('Enter a valid 10-digit Nepal phone number.');if(kind==='drivers'&&v.commissionType!=='None'&&!(Number(v.commissionValue)>0))return alert('Enter a valid commission value for this commission type.');if(kind==='vehicles'&&!v.ownerId)return alert('Select an owner.');const rec={...v,id:v.id||id(),active:v.active??true};if(kind==='drivers'){rec.salary=Number(v.salary||0);rec.commissionValue=Number(v.commissionValue||0);}if(kind==='vehicles')rec.initialOdometer=Number(v.initialOdometer||0);const driverSaved=await saveRecord(kind,rec,!!v.id);if(driverSaved===false)return;if(kind==='drivers'&&v.effectiveFrom){const agreement={id:id(),driverId:rec.id,fixedMonthlySalary:Number(v.salary||0),commissionType:v.commissionType||'None',commissionValue:Number(v.commissionValue||0),effectiveFrom:v.effectiveFrom,effectiveTo:null};const prior=data.agreements.find(a=>a.driverId===rec.id&&a.effectiveFrom===v.effectiveFrom);const agreementSaved=prior?await saveRecord('agreements',{...agreement,id:prior.id},true):await saveRecord('agreements',agreement);if(agreementSaved===false)return;}setModal(null)};return <><Header title={title} desc={`Manage ${title.toLowerCase()} and preserve their historical relationships.`} actions={<button className="primary" onClick={()=>setModal({})}><Plus size={16}/> Add {title.slice(0,-1)}</button>}/><Toolbar search={search} setSearch={setSearch}/><div className="panel table-wrap"><table><thead><tr>{p.fields.map(f=><th key={f[0]}>{f[1]}</th>)}<th>Status</th><th>Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}>{p.fields.map(f=><td key={f[0]}>{f[0]==='ownerId'?data.owners.find(x=>x.id===r.ownerId)?.name||'—':r[f[0]]??'—'}</td>)}<td><span className={'pill '+(r.active===false?'amber':'green')}>{r.active===false?'Archived':'Active'}</span></td><td className="actions"><button className="small-link" onClick={()=>setModal(r)}>Edit</button>{r.active===false?<button className="small-link" onClick={()=>saveRecord(kind,{...r,active:true},true)}>Reactivate</button>:<button className="small-link" onClick={()=>archive(kind,r)}>Deactivate</button>}</td></tr>)}</tbody></table>{!rows.length&&<Empty text={`No ${title.toLowerCase()} found`}/>}</div>{modal&&<FormModal title={`${modal.id?'Edit':'Add'} ${title.slice(0,-1)}`} fields={editFields} initial={modal.id?modal:{}} data={data} onClose={()=>setModal(null)} onSave={save}/>}</>}
function SearchSelect({label,items,value,onChange,display,required=true}){const [q,setQ]=useState('');const filtered=items.filter(i=>display(i).toLowerCase().includes(q.toLowerCase()));return <label>{label}<input placeholder={`Search ${label.toLowerCase()}…`} value={q} onChange={e=>setQ(e.target.value)}/><select required={required} value={value||''} onChange={e=>onChange(e.target.value)}><option value="">Select…</option>{filtered.map(i=><option key={i.id} value={i.id}>{display(i)}</option>)}</select></label>}
function Tracking(p){const {data,activeVehicles,activeDrivers,saveRecord,search,setSearch}=p;const [form,setForm]=useState({readingDate:today(),vehicleId:'',driverId:'',odometer:'',batteryPercent:''}),[tab,setTab]=useState('entry'),[vehicle,setVehicle]=useState(''),[editing,setEditing]=useState(null);const readings=data.readings;const submit=async e=>{e.preventDefault();if(readings.some(r=>r.vehicleId===form.vehicleId&&r.readingDate===form.readingDate&&r.id!==editing?.id))return alert('A reading already exists for this vehicle and date.');const prev=readings.filter(r=>r.vehicleId===form.vehicleId&&r.readingDate<form.readingDate).sort((a,b)=>b.readingDate.localeCompare(a.readingDate))[0];if(prev&&Number(form.odometer)<Number(prev.odometer))return alert('Odometer cannot be lower than the previous reading.');await p.saveRecord('readings',{...form,id:editing?.id||id(),odometer:Number(form.odometer),batteryPercent:form.batteryPercent===''?null:Number(form.batteryPercent)},!!editing);setEditing(null);setForm({...form,vehicleId:'',driverId:'',odometer:'',batteryPercent:''});};const selectedRows=readings.filter(r=>!vehicle||r.vehicleId===vehicle).sort((a,b)=>b.readingDate.localeCompare(a.readingDate));return <><Header title="Daily Vehicle Tracking" desc="Preserve every available odometer reading for mileage history and maintenance."/><div className="tabs"><button className={tab==='entry'?'selected':''} onClick={()=>setTab('entry')}>Daily Reading Entry</button><button className={tab==='report'?'selected':''} onClick={()=>setTab('report')}>Vehicle Reading History</button></div>{tab==='entry'?<form className="panel form-panel" onSubmit={submit}><h3>{editing?'Edit morning reading':'Enter morning reading'}</h3><div className="form-grid"><label>Reading date<input type="date" required value={form.readingDate} onChange={e=>setForm({...form,readingDate:e.target.value})}/></label><SearchSelect label="Vehicle" items={activeVehicles} value={form.vehicleId} onChange={v=>setForm({...form,vehicleId:v})} display={v=>v.registration}/><SearchSelect label="Morning driver" items={activeDrivers} value={form.driverId} onChange={v=>setForm({...form,driverId:v})} display={v=>`${v.name} — ${v.phone}`}/><label>Opening odometer (km)<input type="number" min="0" step="0.1" required value={form.odometer} onChange={e=>setForm({...form,odometer:e.target.value})}/></label><label>Starting battery (%)<input type="number" min="0" max="100" value={form.batteryPercent} onChange={e=>setForm({...form,batteryPercent:e.target.value})}/></label></div><div className="form-actions"><button className="primary"><Save size={15}/>{editing?'Update reading':'Save reading'}</button>{editing&&<button type="button" className="secondary" onClick={()=>{setEditing(null);setForm({readingDate:today(),vehicleId:'',driverId:'',odometer:'',batteryPercent:''})}}>Cancel</button>}</div></form>:<div className="panel table-wrap"><div className="toolbar"><SearchSelect label="Filter vehicle" items={data.vehicles} value={vehicle} onChange={setVehicle} display={v=>v.registration}/><button className="secondary" onClick={()=>setVehicle('')}>All vehicles</button></div><table><thead><tr><th>Date</th><th>Vehicle</th><th>Morning driver</th><th>Odometer</th><th>Battery</th><th>Next interval</th><th>Actions</th></tr></thead><tbody>{selectedRows.map(r=>{const next=readings.filter(x=>x.vehicleId===r.vehicleId&&x.readingDate>r.readingDate).sort((a,b)=>a.readingDate.localeCompare(b.readingDate))[0];return <tr key={r.id}><td>{r.readingDate}</td><td>{data.vehicles.find(v=>v.id===r.vehicleId)?.registration}</td><td>{data.drivers.find(d=>d.id===r.driverId)?.name||'—'}</td><td>{r.odometer} km</td><td>{r.batteryPercent??'—'}%</td><td>{next?`${r.readingDate}–${next.readingDate}: ${Number(next.odometer)-Number(r.odometer)} km`:'No later reading available'}</td><td className="actions"><button className="small-link" onClick={()=>{setEditing(r);setForm({...r,odometer:String(r.odometer),batteryPercent:r.batteryPercent??''});setTab('entry')}}>Edit</button><button className="small-link danger" onClick={()=>p.remove('readings',r)}>Delete</button></td></tr>})}</tbody></table>{!selectedRows.length&&<Empty text="No readings recorded"/>}</div>}</>}
function Rides(p){const {data,activeVehicles,activeDrivers,saveRecord,remove,search,setSearch,commissionFor,csv}=p;const [form,setForm]=useState({rideDate:today(),rideTime:new Date().toTimeString().slice(0,5),bookingType:'Online',vehicleId:'',driverId:'',pickupLocation:'',dropoffLocation:'',appFare:'',agreedFare:'',sameFare:false,passengerName:'',passengerPhone:'',notes:''}),[editing,setEditing]=useState(null),[period,setPeriod]=useState('thisMonth'),[sort,setSort]=useState('newest'),[from,setFrom]=useState(month()+'-01'),[to,setTo]=useState(today());const all=data.rides.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())||String(data.owners.find(o=>o.id===r.ownerId)?.name||'').toLowerCase().includes(search.toLowerCase()));const inPeriod=all.filter(r=>period==='all'||(period==='today'?r.rideDate===today():period==='yesterday'?r.rideDate===new Date(Date.now()-86400000).toLocaleDateString('en-CA'):period==='7days'?r.rideDate>=new Date(Date.now()-7*86400000).toLocaleDateString('en-CA'):period==='thisMonth'?r.rideDate?.startsWith(month()):period==='custom'?r.rideDate>=from&&r.rideDate<=to:true));const clear=()=>setForm({rideDate:today(),rideTime:new Date().toTimeString().slice(0,5),bookingType:'Online',vehicleId:'',driverId:'',pickupLocation:'',dropoffLocation:'',appFare:'',agreedFare:'',sameFare:false,passengerName:'',passengerPhone:'',notes:''});const submit=async e=>{e.preventDefault();if(!form.vehicleId||!form.driverId)return alert('Select a vehicle and driver.');if(Number(form.appFare)<0||Number(form.agreedFare)<0)return alert('Fare cannot be negative.');const fare=Number(form.agreedFare),v=activeVehicles.find(x=>x.id===form.vehicleId),d=activeDrivers.find(x=>x.id===form.driverId);const ag=p.driverAgreement(form.driverId,form.rideDate);if(!ag)return alert('No driver compensation agreement is effective for this driver on the selected ride date. Add or correct the agreement effective date before recording this ride.');const dc=ag.commissionType==='Percentage'?fare*Number(ag.commissionValue||0)/100:ag.commissionType==='Fixed per ride'?Number(ag.commissionValue||0):0;const rec={...form,id:editing?.id||id(),rideDate:form.rideDate,rideTime:form.rideTime,rideDatetime:`${form.rideDate}T${form.rideTime}:00`,vehicleNumber:v?.registration,driverName:d?.name,referenceFare:Number(form.appFare),appFare:Number(form.appFare),agreedFare:fare,nepcabCommission:commissionFor(fare),commissionRateApplied:Number(data.settings.commission??10),driverCommission:dc,driverAgreementId:ag?.id||null,driverCommissionType:ag?.commissionType||'None',driverCommissionValue:Number(ag?.commissionValue||0),ownerId:v?.ownerId||null,rideId:editing?.rideId||`NC-${form.rideDate.replaceAll('-','')}-${Math.random().toString(36).slice(2,7).toUpperCase()}`,vehicleType:'EV'};await saveRecord('rides',rec,!!editing);setEditing(null);clear()};const edit=r=>{setEditing(r);setForm({...form,...r,rideDate:r.rideDate||r.rideDatetime?.slice(0,10),rideTime:r.rideTime||r.rideDatetime?.slice(11,16),appFare:r.appFare??r.referenceFare,agreedFare:r.agreedFare,sameFare:Number(r.appFare)===Number(r.agreedFare)})};const rows=[...inPeriod].sort((a,b)=>sort==='oldest'?(a.rideDate||'').localeCompare(b.rideDate||''):sort==='fareHigh'?Number(b.agreedFare||0)-Number(a.agreedFare||0):sort==='fareLow'?Number(a.agreedFare||0)-Number(b.agreedFare||0):(b.rideDate||'').localeCompare(a.rideDate||''));return <><Header title="Rides" desc="Record completed rides, fares and historical commission calculations." actions={<button className="secondary" onClick={()=>csv(rows.map(r=>({ride_id:r.rideId,date:r.rideDate,time:r.rideTime,booking_type:r.bookingType,vehicle:r.vehicleNumber,driver:r.driverName,app_fare:r.appFare,agreed_fare:r.agreedFare,nepcab_commission:r.nepcabCommission,driver_commission:r.driverCommission,pickup:r.pickupLocation,dropoff:r.dropoffLocation})),'nepcab-rides')}><Download size={15}/> Export CSV</button>}/><form className="panel form-panel" onSubmit={submit}><h3>{editing?'Edit ride':'Ride entry'}</h3><div className="form-grid"><label>Ride date<input type="date" required value={form.rideDate} onChange={e=>setForm({...form,rideDate:e.target.value})}/></label><label>Ride time<input type="time" required value={form.rideTime} onChange={e=>setForm({...form,rideTime:e.target.value})}/></label><label>Booking type<select value={form.bookingType} onChange={e=>setForm({...form,bookingType:e.target.value})}><option>Online</option><option>Offline</option></select></label><SearchSelect label="Vehicle" items={activeVehicles} value={form.vehicleId} onChange={v=>setForm({...form,vehicleId:v})} display={v=>v.registration}/><SearchSelect label="Driver" items={activeDrivers} value={form.driverId} onChange={v=>setForm({...form,driverId:v})} display={v=>`${v.name} — ${v.phone}`}/><label>Passenger name<input required value={form.passengerName} onChange={e=>setForm({...form,passengerName:e.target.value})}/></label><label>Passenger phone<input required value={form.passengerPhone} onChange={e=>setForm({...form,passengerPhone:e.target.value})}/></label><label>Pickup location<input required value={form.pickupLocation} onChange={e=>setForm({...form,pickupLocation:e.target.value})}/></label><label>Drop-off location<input required value={form.dropoffLocation} onChange={e=>setForm({...form,dropoffLocation:e.target.value})}/></label><label>App fare (NPR)<input type="number" min="0" step="0.01" required value={form.appFare} onChange={e=>setForm({...form,appFare:e.target.value,agreedFare:form.sameFare?e.target.value:form.agreedFare})}/></label><label>Agreed fare (NPR)<input type="number" min="0" step="0.01" required disabled={form.sameFare} value={form.agreedFare} onChange={e=>setForm({...form,agreedFare:e.target.value})}/></label><label className="check-label"><input type="checkbox" checked={form.sameFare} onChange={e=>setForm({...form,sameFare:e.target.checked,agreedFare:e.target.checked?form.appFare:form.agreedFare})}/> Agreed fare is the same as App fare</label><label className="span-2">Notes (optional)<textarea value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></label></div><div className="form-actions"><button className="primary"><Save size={15}/>{editing?'Update ride':'Save ride'}</button>{editing&&<button type="button" className="secondary" onClick={()=>{setEditing(null);clear()}}>Cancel edit</button>}</div></form><div className="toolbar"><div className="search"><Search size={16}/><input placeholder="Search ride, vehicle, driver, owner…" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={period} onChange={e=>setPeriod(e.target.value)}><option value="thisMonth">This month</option><option value="today">Today</option><option value="yesterday">Yesterday</option><option value="7days">Last 7 days</option><option value="all">All rides</option><option value="custom">Custom date range</option></select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="fareHigh">Agreed fare: high to low</option><option value="fareLow">Agreed fare: low to high</option></select>{period==='custom'&&<><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/><input type="date" value={to} onChange={e=>setTo(e.target.value)}/></>}</div><div className="panel table-wrap"><table><thead><tr><th>Ride ID</th><th>Date/time</th><th>Booking</th><th>Vehicle</th><th>Driver</th><th>App fare</th><th>Agreed fare</th><th>NepCab commission</th><th>Actions</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{r.rideId||r.ride_id}</td><td>{r.rideDate} {r.rideTime}</td><td>{r.bookingType}</td><td>{r.vehicleNumber||data.vehicles.find(v=>v.id===r.vehicleId)?.registration}</td><td>{r.driverName||data.drivers.find(d=>d.id===r.driverId)?.name}</td><td>{money(r.appFare??r.referenceFare)}</td><td>{money(r.agreedFare)}</td><td>{money(r.nepcabCommission)}</td><td className="actions"><button className="small-link" onClick={()=>edit(r)}>Edit</button><button className="small-link danger" onClick={()=>remove('rides',r)}>Delete</button></td></tr>)}</tbody></table>{!rows.length&&<Empty text="No rides found"/>}</div></>}
function Expenses(p){const {data,activeVehicles,activeDrivers,saveRecord,search,setSearch,csv}=p;const [f,setF]=useState({expenseDate:today(),category:'',vehicleId:'',driverId:'',amount:'',description:''}),[tab,setTab]=useState('entries'),[target,setTarget]=useState(''),[period,setPeriod]=useState(month()),[cat,setCat]=useState('');const categories=data.categories.filter(c=>c.active!==false);const rows=data.expenses.filter(e=>JSON.stringify(e).toLowerCase().includes(search.toLowerCase()));const submit=async e=>{e.preventDefault();if(!f.vehicleId&&!f.driverId)return alert('Select at least a vehicle or a driver.');if(Number(f.amount)<=0)return alert('Enter an amount greater than zero.');const v=data.vehicles.find(x=>x.id===f.vehicleId);await saveRecord('expenses',{...f,id:id(),amount:Number(f.amount),ownerId:v?.ownerId||null});setF({...f,vehicleId:'',driverId:'',amount:'',description:''})};const hist=rows.filter(e=>(e.expenseDate||'').startsWith(period)&&(!target||(tab==='vehicleHistory'?e.vehicleId===target:e.driverId===target)));const total=hist.reduce((s,e)=>s+Number(e.amount),0);return <><Header title="Expenses" desc="Record vehicle and driver expenses; all vehicle-linked expenses reduce owner earnings."/><div className="tabs"><button className={tab==='entries'?'selected':''} onClick={()=>setTab('entries')}>Expense entries</button><button className={tab==='vehicleHistory'?'selected':''} onClick={()=>setTab('vehicleHistory')}>Vehicle expense history</button><button className={tab==='driverHistory'?'selected':''} onClick={()=>setTab('driverHistory')}>Driver expense history</button></div>{tab==='entries'&&<><form className="panel form-panel" onSubmit={submit}><h3>Record expense</h3><div className="form-grid"><label>Date<input type="date" required value={f.expenseDate} onChange={e=>setF({...f,expenseDate:e.target.value})}/></label><label>Category<select required value={f.category} onChange={e=>setF({...f,category:e.target.value})}><option value="">Select category…</option>{categories.map(c=><option key={c.id} value={c.name}>{c.name}</option>)}</select><button type="button" className="small-link" onClick={async()=>{const name=prompt("New expense category name");if(name?.trim()){const ok=await saveRecord("categories",{id:id(),name:name.trim(),active:true});if(ok)setF(x=>({...x,category:name.trim()}));}}}>+ Add new category</button></label><SearchSelect label="Vehicle (optional)" items={activeVehicles} value={f.vehicleId} onChange={v=>setF({...f,vehicleId:v})} display={v=>v.registration} required={false}/><SearchSelect label="Driver (optional)" items={activeDrivers} value={f.driverId} onChange={v=>setF({...f,driverId:v})} display={v=>`${v.name} — ${v.phone}`} required={false}/><label>Amount (NPR)<input type="number" min="0.01" step="0.01" required value={f.amount} onChange={e=>setF({...f,amount:e.target.value})}/></label><label>Description<input value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label></div><p className="hint">At least one of Vehicle or Driver must be selected. If both are selected, the expense is counted once.</p><button className="primary"><Save size={15}/> Save expense</button></form><Toolbar search={search} setSearch={setSearch}/><div className="panel table-wrap"><table><thead><tr><th>Date</th><th>Category</th><th>Vehicle</th><th>Driver</th><th>Description</th><th>Amount</th><th>Action</th></tr></thead><tbody>{rows.map(e=><tr key={e.id}><td>{e.expenseDate}</td><td>{e.category}</td><td>{data.vehicles.find(v=>v.id===e.vehicleId)?.registration||'—'}</td><td>{data.drivers.find(d=>d.id===e.driverId)?.name||'—'}</td><td>{e.description}</td><td>{money(e.amount)}</td><td><button className="small-link danger" onClick={()=>p.remove('expenses',e)}>Delete</button></td></tr>)}</tbody></table>{!rows.length&&<Empty text="No expenses recorded"/>}</div></>}{tab!=='entries'&&<><div className="period-row"><label>Reporting period<input type="month" value={period} onChange={e=>setPeriod(e.target.value)}/></label><SearchSelect label={tab==='vehicleHistory'?'Vehicle':'Driver'} items={tab==='vehicleHistory'?activeVehicles:activeDrivers} value={target} onChange={setTarget} display={x=>tab==='vehicleHistory'?x.registration:`${x.name} — ${x.phone}`}/><div className="net-card"><small>Total expenses</small><b>{money(total)}</b></div></div><div className="panel table-wrap"><table><thead><tr><th>Date</th><th>Category</th><th>Vehicle</th><th>Driver</th><th>Description</th><th>Amount</th></tr></thead><tbody>{hist.map(e=><tr key={e.id}><td>{e.expenseDate}</td><td>{e.category}</td><td>{data.vehicles.find(v=>v.id===e.vehicleId)?.registration||'—'}</td><td>{data.drivers.find(d=>d.id===e.driverId)?.name||'—'}</td><td>{e.description}</td><td>{money(e.amount)}</td></tr>)}</tbody></table>{!hist.length&&<Empty text="No expenses for this selection and period"/>}</div></>}</>}
function nextMonth(m){const [y,mo]=m.split('-').map(Number);const d=new Date(y,mo,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;}
function Payroll(p){const {data,activeDrivers,search,setSearch,period,setPeriod,saveRecord,csv}=p;const [selected,setSelected]=useState('');const drivers=data.drivers.filter(d=>!search||`${d.name} ${d.phone}`.toLowerCase().includes(search.toLowerCase()));const rows=drivers.map(d=>{const rs=data.rides.filter(r=>r.driverId===d.id&&(r.rideDate||r.rideDatetime||'').slice(0,7)===period);const commission=rs.reduce((s,r)=>s+Number(r.driverCommission||0),0);const agreementFor=m=>data.agreements.filter(a=>a.driverId===d.id&&a.effectiveFrom<=`${m}-31`&&(!a.effectiveTo||a.effectiveTo>=`${m}-01`)).sort((a,b)=>b.effectiveFrom.localeCompare(a.effectiveFrom))[0];const ag=agreementFor(period);const salary=Number(ag?.fixedMonthlySalary??d.salary??0);const earned=salary+commission;const driverExpenses=data.expenses.filter(e=>e.driverId===d.id&&(e.expenseDate||'').slice(0,7)===period).reduce((s,e)=>s+Number(e.amount||0),0);const first=[...data.rides.filter(r=>r.driverId===d.id).map(r=>(r.rideDate||r.rideDatetime||'').slice(0,7)),...data.agreements.filter(a=>a.driverId===d.id).map(a=>a.effectiveFrom.slice(0,7))].filter(Boolean).sort()[0]||period;let accrued=0;for(let m=first;m<=period;m=nextMonth(m)){const a=agreementFor(m);accrued+=Number(a?.fixedMonthlySalary??(m===period?d.salary:0)??0)+data.rides.filter(r=>r.driverId===d.id&&(r.rideDate||r.rideDatetime||'').slice(0,7)===m).reduce((s,r)=>s+Number(r.driverCommission||0),0);}const payments=data.driverPayments.filter(x=>x.driverId===d.id&&(x.periodMonth||'').slice(0,7)<=period);const paid=payments.filter(x=>(x.periodMonth||'').slice(0,7)===period).reduce((s,x)=>s+Number(x.amount),0);const paidToDate=payments.reduce((s,x)=>s+Number(x.amount),0);return{d,rides:rs.length,commission,salary,earned,driverExpenses,paid,balance:accrued-paidToDate}});const pay=async r=>{const amount=prompt(`Amount paid to ${r.d.name}. Outstanding: ${money(r.balance)}`,String(Math.max(0,r.balance)));if(amount===null)return;if(!(Number(amount)>0)||Number(amount)>r.balance)return alert('Enter an amount greater than zero and no more than the outstanding balance.');await saveRecord('driverPayments',{id:id(),driverId:r.d.id,periodMonth:`${period}-01`,amount:Number(amount),paymentDate:today(),note:'Recorded external settlement'});};return <><Header title="Driver Payroll" desc="Calculated driver earnings and records of payments made outside the application." actions={<input type="month" value={period} onChange={e=>setPeriod(e.target.value)}/>}/><Toolbar search={search} setSearch={setSearch} placeholder="Search driver name or phone…" actions={<button className="secondary" onClick={()=>csv(rows.map(r=>({driver:r.d.name,phone:r.d.phone,rides:r.rides,fixed_salary:r.salary,ride_commission:r.commission,total_earnings:r.earned,driver_expenses_info:r.driverExpenses,paid:r.paid,balance:r.balance})),'driver-payroll-'+period)}><Download size={15}/> Export CSV</button>}/><div className="panel table-wrap"><table><thead><tr><th>Driver</th><th>Rides</th><th>Fixed salary</th><th>Ride commission</th><th>Total earnings</th><th>Driver expenses (info)</th><th>Amount paid</th><th>Balance</th><th>Action</th></tr></thead><tbody>{rows.map(r=><tr key={r.d.id}><td><b>{r.d.name}</b><small>{r.d.phone}</small></td><td>{r.rides}</td><td>{money(r.salary)}</td><td>{money(r.commission)}</td><td>{money(r.earned)}</td><td>{money(r.driverExpenses)}</td><td>{money(r.paid)}</td><td><b>{money(r.balance)}</b></td><td><button className="small-link" disabled={r.balance<=0} onClick={()=>pay(r)}>Settle</button></td></tr>)}</tbody></table>{!rows.length&&<Empty text="No drivers found"/>}</div><p className="hint">Balance includes previous unpaid earnings carried forward, less all recorded payments through the selected period. Driver expenses are displayed for information and are not deducted from salary. Partial payments are supported. Payments are records only; transfers happen outside NepCab.</p><h3>Settlement history</h3><div className="panel table-wrap"><table><thead><tr><th>Driver</th><th>Payroll period</th><th>Payment date/time</th><th>Amount</th></tr></thead><tbody>{data.driverPayments.filter(x=>!search||data.drivers.find(d=>d.id===x.driverId)?.name.toLowerCase().includes(search.toLowerCase())).map(x=><tr key={x.id}><td>{data.drivers.find(d=>d.id===x.driverId)?.name}</td><td>{x.periodMonth?.slice(0,7)}</td><td>{x.paymentDate} {x.createdAt?new Date(x.createdAt).toLocaleTimeString():''}</td><td>{money(x.amount)}</td></tr>)}</tbody></table></div></>}
function ownerCalc(ownerId,p,period){const {data}=p;const vids=data.vehicles.filter(v=>v.ownerId===ownerId).map(v=>v.id);const rides=data.rides.filter(r=>vids.includes(r.vehicleId)&&(r.rideDate||'').slice(0,7)===period);const expenses=data.expenses.filter(e=>vids.includes(e.vehicleId)&&(e.expenseDate||'').slice(0,7)===period);const gross=rides.reduce((s,r)=>s+Number(r.agreedFare||0),0),commission=rides.reduce((s,r)=>s+Number(r.nepcabCommission||0),0),driver=rides.reduce((s,r)=>s+Number(r.driverCommission||0),0),cost=expenses.reduce((s,e)=>s+Number(e.amount||0),0);return{vids,rides,expenses,gross,commission,driver,cost,net:gross-commission-driver-cost}}
function Settlements(p){const {data,activeOwners,search,setSearch,period,setPeriod,saveRecord,csv}=p;const [owner,setOwner]=useState('');const rows=data.owners.filter(o=>!search||`${o.name} ${o.phone}`.toLowerCase().includes(search.toLowerCase())).map(o=>{const c=ownerCalc(o.id,p,period);const months=[...data.rides.filter(r=>ownerCalc(o.id,p,(r.rideDate||'').slice(0,7)).rides.length).map(r=>(r.rideDate||'').slice(0,7)),...data.expenses.filter(e=>data.vehicles.some(v=>v.id===e.vehicleId&&v.ownerId===o.id)).map(e=>(e.expenseDate||'').slice(0,7))].filter(Boolean).sort();const first=months[0]||period;let accrued=0;for(let m=first;m<=period;m=nextMonth(m))accrued+=ownerCalc(o.id,p,m).net;const payments=data.ownerPayments.filter(x=>x.ownerId===o.id&&(x.periodMonth||'').slice(0,7)<=period);const paid=payments.filter(x=>(x.periodMonth||'').slice(0,7)===period).reduce((s,x)=>s+Number(x.amount),0);const paidToDate=payments.reduce((s,x)=>s+Number(x.amount),0);return{o,c,paid,balance:accrued-paidToDate}});const settle=async r=>{if(r.balance<=0)return;const amount=prompt(`Record owner payment to ${r.o.name}. Outstanding: ${money(r.balance)}`,String(r.balance));if(amount===null)return;if(!(Number(amount)>0)||Number(amount)>r.balance)return alert('Enter an amount greater than zero and no more than the outstanding balance.');await saveRecord('ownerPayments',{id:id(),ownerId:r.o.id,periodMonth:`${period}-01`,amount:Number(amount),paymentDate:today(),breakdown:{gross:r.c.gross,commission:r.c.commission,driverCommission:r.c.driver,expenses:r.c.cost,net:r.c.net}})};const detail=rows.find(x=>x.o.id===owner);return <><Header title="Owner Settlements" desc="Fleet-wide owner earnings, vehicle expense deductions and settlement history." actions={<input type="month" value={period} onChange={e=>setPeriod(e.target.value)}/>}/><Toolbar search={search} setSearch={setSearch} placeholder="Search owner name or phone…" actions={<button className="secondary" onClick={()=>csv(rows.map(r=>({owner:r.o.name,vehicles:r.c.vids.length,rides:r.c.rides.length,gross:r.c.gross,nepcab_commission:r.c.commission,driver_commission:r.c.driver,vehicle_expenses:r.c.cost,owner_earnings:r.c.net,paid:r.paid,balance:r.balance})),'owner-settlements-'+period)}><Download size={15}/> Export CSV</button>}/><div className="panel table-wrap"><table><thead><tr><th>Owner</th><th>Vehicles</th><th>Rides</th><th>Gross agreed fares</th><th>NepCab commission</th><th>Driver commission</th><th>Vehicle expenses</th><th>Owner earnings</th><th>Paid</th><th>Balance</th><th>Action</th></tr></thead><tbody>{rows.map(r=><tr key={r.o.id}><td><button className="small-link" onClick={()=>setOwner(owner===r.o.id?'':r.o.id)}>{r.o.name}</button><small>{r.o.phone}</small></td><td>{r.c.vids.length}</td><td>{r.c.rides.length}</td><td>{money(r.c.gross)}</td><td>{money(r.c.commission)}</td><td>{money(r.c.driver)}</td><td>{money(r.c.cost)}</td><td>{money(r.c.net)}</td><td>{money(r.paid)}</td><td><b>{money(r.balance)}</b></td><td><button className="small-link" disabled={r.balance<=0} onClick={()=>settle(r)}>Settle</button></td></tr>)}</tbody></table>{!rows.length&&<Empty text="No owners found"/>}</div>{detail&&<div className="panel form-panel"><div className="panel-title"><h3>{detail.o.name} — vehicle breakdown</h3><button className="small-link" onClick={()=>setOwner('')}>Close</button></div><table><thead><tr><th>Vehicle</th><th>Rides</th><th>Gross fares</th><th>NepCab commission</th><th>Driver commission</th><th>Expenses</th><th>Owner net</th></tr></thead><tbody>{data.vehicles.filter(v=>v.ownerId===owner).map(v=>{const rs=detail.c.rides.filter(r=>r.vehicleId===v.id),es=detail.c.expenses.filter(e=>e.vehicleId===v.id),g=rs.reduce((s,r)=>s+Number(r.agreedFare||0),0),n=rs.reduce((s,r)=>s+Number(r.nepcabCommission||0),0),d=rs.reduce((s,r)=>s+Number(r.driverCommission||0),0),ex=es.reduce((s,e)=>s+Number(e.amount||0),0);return <tr key={v.id}><td>{v.registration}</td><td>{rs.length}</td><td>{money(g)}</td><td>{money(n)}</td><td>{money(d)}</td><td>{money(ex)}</td><td>{money(g-n-d-ex)}</td></tr>})}</tbody></table></div>}<h3>Settlement history</h3><div className="panel table-wrap"><table><thead><tr><th>Owner</th><th>Period</th><th>Payment date/time</th><th>Amount</th></tr></thead><tbody>{data.ownerPayments.map(x=><tr key={x.id}><td>{data.owners.find(o=>o.id===x.ownerId)?.name}</td><td>{x.periodMonth?.slice(0,7)}</td><td>{x.paymentDate} {x.createdAt?new Date(x.createdAt).toLocaleTimeString():''}</td><td>{money(x.amount)}</td></tr>)}</tbody></table></div></>}
function Dashboard(p){const {data,totals,period,setPeriod,go}=p;return <><Header title="Dashboard" desc="Operational and financial overview from the connected modules." actions={<input type="month" value={period} onChange={e=>setPeriod(e.target.value)}/>}/><div className="stats-grid"><Stat label="Active vehicles" value={data.vehicles.filter(x=>x.active!==false).length}/><Stat label="Active drivers" value={data.drivers.filter(x=>x.active!==false).length}/><Stat label="Rides this period" value={totals.rides}/><Stat label="Gross agreed fares" value={money(totals.gross)}/><Stat label="NepCab commission" value={money(totals.commission)}/><Stat label="Driver commissions" value={money(totals.driverCommission)}/><Stat label="Total recorded expenses" value={money(totals.expenses)}/><Stat label="Recorded odometer readings" value={data.readings.length}/></div><div className="quick-grid">{[['Add a ride','Record completed ride','Rides'],['Daily reading','Record vehicle odometer','Daily Tracking'],['Record expense','Add vehicle or driver expense','Expenses'],['Owner settlements','Review owner earnings','Owner Settlements'],['Driver payroll','Review driver earnings','Driver Payroll'],['Reports','Company-wide reports','Reports']].map(([a,b,c])=><button className="quick-card" key={a} onClick={()=>go(c)}><b>{a}</b><small>{b}</small></button>)}</div></>}
function Stat({label,value}){return <div className="stat"><span>{label}</span><strong>{value}</strong></div>}
function Reports(p){const {data,totals,period,setPeriod,go,csv}=p;return <><Header title="Reports" desc="Central overview; detailed records remain in their respective modules." actions={<input type="month" value={period} onChange={e=>setPeriod(e.target.value)}/>}/><div className="stats-grid"><Stat label="Completed rides" value={totals.rides}/><Stat label="Gross agreed fares" value={money(totals.gross)}/><Stat label="NepCab commission" value={money(totals.commission)}/><Stat label="Driver commissions" value={money(totals.driverCommission)}/><Stat label="Total recorded expenses" value={money(totals.expenses)}/></div><div className="report-links">{[['Rides','Rides'],['Expenses','Expenses'],['Driver payroll','Driver Payroll'],['Owner settlements','Owner Settlements'],['Mileage history','Daily Tracking']].map(([label,page])=><button className="report-link" key={page} onClick={()=>go(page)}>{label} →</button>)}</div><button className="secondary" onClick={()=>csv(data.rides.filter(r=>(r.rideDate||'').startsWith(period)).map(r=>({ride_id:r.rideId,date:r.rideDate,vehicle:r.vehicleNumber,driver:r.driverName,agreed_fare:r.agreedFare,nepcab_commission:r.nepcabCommission})),'nepcab-report-'+period)}><Download size={15}/> Export period rides CSV</button></>}
function SettingsPage(p){const {data,setData,saveRecord,supabase}=p;const [rate,setRate]=useState(data.settings.commission??10),[category,setCategory]=useState('');const add=async()=>{if(!category.trim())return;await saveRecord('categories',{id:id(),name:category.trim(),active:true});setCategory('')};const save=async()=>{if(Number(rate)<0||Number(rate)>100)return alert('Commission rate must be between 0 and 100.');if(supabase){const {error}=await supabase.from('commission_rates').insert({rate:Number(rate),basis:'agreed_fare',applies_to:'both',effective_from:today()});if(error)return alert(error.message);}setData(d=>({...d,settings:{...d.settings,commission:Number(rate)}}));p.flash('New commission rate saved. Existing rides retain their stored commission.');};return <><Header title="Settings" desc="Prospective commission rate and permanent expense categories."/><div className="settings-grid"><div className="panel setting-card"><h3>NepCab commission</h3><p>Proposed policy: 10% of agreed fare on Online and Offline rides. Owner confirmation is still required.</p><label>Commission rate (%)<input type="number" min="0" max="100" value={rate} onChange={e=>setRate(e.target.value)}/></label><button className="primary" onClick={save}>Save new effective rate</button><small>New rate is prospective; historical ride calculations remain unchanged.</small></div><div className="panel setting-card"><h3>Expense categories</h3><div className="inline-form"><input placeholder="New category name" value={category} onChange={e=>setCategory(e.target.value)}/><button className="primary" onClick={add}><Plus size={15}/> Add</button></div>{data.categories.map(c=><div className="category-row" key={c.id}>{c.name}<span className="pill green">{c.active===false?'Inactive':'Active'}</span><button className="small-link" onClick={()=>p.saveRecord('categories',{...c,active:c.active===false},true)}>{c.active===false?'Reactivate':'Deactivate'}</button></div>)}</div><div className="panel setting-card"><h3>Database connection</h3><p>{supabase?'Supabase configured. Authenticated CRUD is enabled.':'Local demo mode. Configure .env.local to connect Supabase.'}</p><small>Use only the Supabase publishable/anon key in this frontend. Never use service_role.</small></div></div></>}


export default App;
